CREATE TABLE src_srm.srm_onboarding(id BIGINT AUTO_INCREMENT PRIMARY KEY,application_no VARCHAR(32) UNIQUE,supplier_name VARCHAR(200),category_code VARCHAR(32),contact_name VARCHAR(50),contact_phone VARCHAR(32),risk_level VARCHAR(16),status VARCHAR(20) DEFAULT 'DRAFT',workflow_instance_id BIGINT,created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE src_srm.srm_qualification(id BIGINT AUTO_INCREMENT PRIMARY KEY,onboarding_id BIGINT,qualification_type VARCHAR(50),certificate_no VARCHAR(64),expire_date DATE,audit_result VARCHAR(20),file_name VARCHAR(255));
CREATE TABLE src_srm.srm_rfq(id BIGINT AUTO_INCREMENT PRIMARY KEY,rfq_no VARCHAR(32) UNIQUE,title VARCHAR(200),material_code VARCHAR(32),quantity DECIMAL(18,4),required_date DATE,status VARCHAR(20) DEFAULT 'DRAFT',winner_supplier_code VARCHAR(32),source_requisition_no VARCHAR(32),created_by VARCHAR(32),created_at DATETIME(3) DEFAULT CURRENT_TIMESTAMP(3));
CREATE TABLE src_srm.srm_supplier_quote(id BIGINT AUTO_INCREMENT PRIMARY KEY,rfq_id BIGINT,supplier_code VARCHAR(32),unit_price DECIMAL(18,4),delivery_date DATE,payment_terms VARCHAR(100),score DECIMAL(8,2),status VARCHAR(20) DEFAULT 'SUBMITTED',UNIQUE KEY uk_rfq_supplier(rfq_id,supplier_code));
